fallbackCss:
/*
 * Values match calculateSizeAdjustValues in the installed Next font-utils module.
 * They preserve Next's metric adjustments while adding installed Linux aliases.
 * Liberation Serif is the metric-compatible Linux alternative to Times New Roman.
 * Keep these overrides with the font registry when updating the pinned fonts.
 */
@font-face {
  font-family: "Cormorant Metric Fallback";
  src: local("Times New Roman"), local("Liberation Serif");
  ascent-override: 95.27%;
  descent-override: 29.59%;
  line-gap-override: 0%;
  size-adjust: 96.98%;
}

@font-face {
  font-family: "Inter Metric Fallback";
  src: local("Arial"), local("Liberation Sans");
  ascent-override: 90.44%;
  descent-override: 22.52%;
  line-gap-override: 0%;
  size-adjust: 107.12%;
}

@font-face {
  font-family: "Jost Metric Fallback";
  src: local("Arial"), local("Liberation Sans");
  ascent-override: 111.45%;
  descent-override: 39.06%;
  line-gap-override: 0%;
  size-adjust: 96.01%;
}

@font-face {
  font-family: "Playfair Metric Fallback";
  src: local("Times New Roman"), local("Liberation Serif");
  ascent-override: 97.25%;
  descent-override: 22.56%;
  line-gap-override: 0%;
  size-adjust: 111.26%;
}
